function dijkstra(list,a,b,cost){
  const dist={},prev={},done=new Set();IDS.forEach(c=>dist[c]=Infinity);dist[a]=0;
  for(;;){
    let u=null;for(const c of IDS)if(!done.has(c)&&dist[c]<Infinity&&(u===null||dist[c]<dist[u]))u=c;
    if(u===null)return null;if(u===b)break;done.add(u);
    for(const ri of ADJ[u]){const r=list[ri],w=cost(r);if(w===Infinity)continue;const v=r.a===u?r.b:r.a;if(dist[u]+w<dist[v]){dist[v]=dist[u]+w;prev[v]=ri}}
  }
  const edges=[];let c=b;while(c!==a){const ri=prev[c];edges.push(ri);const r=list[ri];c=r.a===c?r.b:r.a}
  return{cost:dist[b],edges};
}
